INSERT INTO `products` (`id`, `name`, `original_price`, `offer_price`, `discount`, `description`, `created`, `modified`, `category_id`, `company_id`) VALUES
(1, 'Non-stick Dosa Tawa Royal Velvet 28cm, Induction bottom, Soft-touch Handle, Virgin Grade Aluminium, 3mm, with warranty', 1700, 999, 701, 'Transform your kitchen with the stylish Wonderchef Royal Velvet Dosa Tawa. This premium cookware features a marble-finished pure grade virgin aluminium body for quick and even heat distribution. Enjoy healthy, oil-free meals with its 100% PFOA-free, 5-layer Meta Tuff non-stick coating. Ideal for making dosas, chillas, parathas, and pancakes, this durable tawa has a 3mm thickness and ergonomic soft-touch handles that stay cool. Suitable for gas stoves, ceramic plates, hobs, hot plates, and induction plates. Inspired by Italian design and adhering to German quality standards, it comes with a reliable Wonderchef warranty. Upgrade your cooking with Wonderchef!', '2024-07-06 09:32:57', '2024-07-06 09:32:57', 3, 0),
(2, 'Roti Non Stick Tawa 25 cm with  Induction Bottom, Wooden Handle, Hard Anodized Aluminium, 4.06 mm with Warranty', 1700, 1099, 601, 'Enhance your kitchen with the Roti Non Stick Tawa 25 cm, featuring an induction bottom and a stylish wooden handle. Made from hard anodized aluminium, this 4.06 mm thick tawa ensures even heat distribution for perfect rotis every time. The premium non-stick coating allows for healthy, oil-free cooking and easy cleanup. Its versatile design makes it suitable for use on induction cooktops, gas stoves, and more. Durable and reliable, this tawa comes with a warranty for your peace of mind. Upgrade your cookware collection with this high-quality, non-stick roti tawa and enjoy delicious, evenly cooked rotis every day! by wonderchef.', '2024-07-06 09:47:48', '2024-07-06 09:57:51', 3, 0),
(3, 'Stanton Stainless Steel 30 cm Non-stick Dosa Tawa, 2.5 mm', 4200, 2399, NULL, 'Upgrade your kitchen with the Stanton Stainless Steel 30 cm Non-stick Dosa Tawa, 2.5 mm. This premium tawa ensures quick and even heat distribution with its pure stainless steel construction. The advanced non-stick coating is PFOA-free, allowing you to cook with minimal oil for healthier meals. Ideal for dosas, parathas, pancakes, and more, its 2.5 mm thickness ensures durability and long-lasting performance. The ergonomic handle stays cool, providing a secure grip. Compatible with gas stoves, ceramic plates, hobs, and induction plates, this tawa combines style and functionality. Elevate your cooking experience with the Stanton Non-stick Dosa Tawa! by wonderchef', '2024-07-06 09:52:42', '2024-07-06 09:52:42', 3, 0),
(4, 'Inducta Multi Pan with 7-Cavity Multi Pan: Healthy, Non-stick, and Versatile Cooking Solution |  Ideal For mini uttapams, round mini omelets, pancakes, round shape eggs, chillas, set dosas', NULL, 0, NULL, 'Enhance your culinary skills with the Inducta 7-Cavity Multi Pan, designed for ultimate convenience and healthy cooking. This PFOA-free, die-cast pan features seven cavities perfect for making mini uttapams, round mini omelets, pancakes, round-shaped eggs, chillas, and set dosas. The 270 ml, 3mm thick pan ensures even heat distribution and long-lasting durability. Compatible with both gas and induction cooktops, it offers versatility and ease of use. With a sleek black finish and a 2-year warranty, the Inducta Multi Pan is the ideal addition to any kitchen. Elevate your cooking experience with this stylish and functional non-stick multi pan!', '2024-07-06 10:01:22', '2024-07-06 10:01:22', 3, 0),
(5, 'Granite Non-stick Cookware Set, 4Pc (Frying Pan With Lid, Wok, Dosa Tawa), 3.5mm, Induction Bottom, Soft-Touch Handles, Pure Grade Aluminium', NULL, 0, NULL, 'Enhance your culinary skills with the Wonderchef Granite Non-stick Cookware Set, 4Pc. This set includes a 26cm Wok, Fry Pan with Lid, and Dosa Tawa, all designed with a stunning granite finish. Made from pure grade aluminium for even heat distribution, this cookware is PFOA-free with a Meta Tuff 5-layer non-stick coating, ensuring healthy, low-fat cooking. Suitable for use on gas stoves, induction, hot plates, hobs, and ceramic plates, the set also features soft-touch handles for comfort. Inspired by Italian design and adhering to German quality standards, it comes with a 2-year warranty. Elevate your kitchen! by wonderchef!', '2024-07-06 10:06:22', '2024-07-06 10:06:22', 3, 0),
(6, 'Forza Pre-Seasoned Cast-Iron 25 cm Dosa Tawa Pan: Traditional Cooking Excellence', NULL, 0, NULL, 'Rediscover the magic of traditional cooking with the Forza Pre-Seasoned Cast-Iron 25 cm Dosa Tawa Pan. Crafted for old-style slow-cooking, this 3.8 mm thick, induction-friendly tawa ensures even heat distribution for perfect dosas, chillas, parathas, crepes, and pancakes. Pre-seasoned with 100% vegetable oil, it enhances iron content in your meals, ideal for those with iron deficiency. With a sturdy handle for a firm grip and a lifetime exchange warranty, this durable tawa is built to last. Suitable for all cooking surfaces, oven, grill, and freezer safe, Forza brings the timeless charm of cast-iron cooking to your kitchen.', '2024-07-06 10:09:39', '2024-07-06 10:09:39', 3, 0),
(8, 'Duralife Die-cast 28 cm Dosa Tawa - Copper', NULL, 0, NULL, 'Upgrade your kitchen with Duralife Die-cast 28 cm Dosa Tawa. This exquisite copper-colored tawa, with its reddish-brown hues and light wood-finish soft-touch handle, adds a touch of elegance to your cooking space. Crafted from pure-grade die-cast aluminium and featuring a 5-layer Duramax Japanese non-stick coating, this tawa ensures minimal oil use for healthy cooking. It\'s 100% PFOA-free and designed for durability, with a 2-year warranty for peace of mind. Suitable for all cooking surfaces, it offers versatility and energy efficiency, making it a perfect addition to any kitchen.  Key Features: Stylish Design: Elegant copper color with light wood-finish soft-touch handle. Healthy Cooking: 5-layer Duramax Japanese non-stick coating for minimal oil use, PFOA-free. Durable Construction: Pure-grade die-cast aluminium retains shape, 4mm thick base and rim for higher strength. Versatile Use: Compatible with gas, hot plates, infrared, and ceramic cooktops. Energy Efficient: Offers 9 times better heat conduction, cooking meals faster and saving energy. Ideal For: Healthy Meals: Perfect for making dosas, pancakes, chillas, and more with minimal oil. Gifting: An ideal choice for gifting with its beautiful looks and superior features. Durable Use: Sturdy construction ensures long-lasting performance even with regular use. Elevate your cooking experience with the Wonderchef Duralife Die-cast 28 cm Dosa Tawa, combining style, health, and durability in one perfect package.', '2024-07-06 10:14:58', '2024-07-06 10:14:58', 3, 0),
(9, 'Royal Velvet Non-stick 30cm Dosa Tawa with soft touch Handle', NULL, 0, NULL, 'Elevate your cooking experience with the Wonderchef Royal Velvet Non-stick 30cm Dosa Tawa. Featuring a sleek marble finish and a regal purple hue, this tawa adds style to your kitchen. Crafted from virgin aluminium with a 3mm thick base, it ensures even heat distribution for perfect cooking. The METATUFF 5-layer non-stick coating is PFOA-free and guarantees healthy, low-oil meals. Induction ready and versatile, it\'s perfect for dosas, uttapams, omelettes, and more. The soft-touch handles provide a firm grip, making cooking effortless. Enjoy peace of mind with a 2-year warranty and the assurance of Italian design and German quality standards.  Key Features: Aesthetic Delight: Sleek marble finish with a regal purple hue. Non-stick Excellence: METATUFF 5-layer non-stick coating, PFOA-free. Effortless Cooking: Virgin aluminium ensures even heat distribution. Versatility: Suitable for gas stoves and induction cooktops. Easy Handling: Soft-touch handles provide a strong grip. by wonderchef', '2024-07-06 10:20:11', '2024-07-06 10:20:11', 3, 0),
(10, 'Duralite Die-Cast Non-Stick Pans , Fry Pan, Dosa Tawa', NULL, 0, NULL, 'Elevate your cooking with Duralite Die-Cast Non-Stick Pans tawa. This set includes a 24 cm Kadhai with Lid, 24 cm Fry Pan, and 28 cm Dosa Tawa, all featuring a robust die-cast design and a healthy German Meta-tuff non-stick coating. Made from virgin aluminium, these pans ensure excellent heat distribution and require minimal oil for cooking, promoting healthier meals. The ergonomic cool-touch handles provide a comfortable grip, and the non-stick surface makes cleaning a breeze. With a 2-year warranty and stylish grey finish, this set combines quality, health, and convenience for your kitchen.', '2024-07-06 10:26:32', '2024-07-06 10:26:32', 3, 0),
(11, 'Nigella 3-Ply 26 cm Non-Stick Roti Tawa - Ultimate Cooking Companion', NULL, 0, NULL, 'Elevate your cooking with the Nigella 3-Ply 26 cm Roti Tawa. Its enhanced multi-layered construction features an aluminium core sandwiched between two high-grade steel layers, ensuring exceptional heat conduction and durability. The 4mm thickness guarantees perfectly cooked rotis with even heat distribution, requiring less oil for healthier meals. Designed for all cooktops, including gas, electric, and induction, this tawa offers versatile cooking. The riveted stay-cool handle provides safe and comfortable handling. Backed by a 10-year warranty, this tawa is perfect for both home chefs and professionals.  Key Features: Enhanced Construction: 3-ply with aluminium core for exceptional heat conduction. Perfect Cooking: 4mm thickness ensures even heat distribution and perfect rotis. Healthier Meals: Requires less oil for healthy cooking. All Cooktop Compatibility: Works with gas, electric, and induction cooktops. Stay-Cool Handle: Riveted handle ensures safe and comfortable handling.', '2024-07-06 12:26:50', '2024-07-06 12:26:50', 3, 0),
(12, 'Duralife Die-Cast 24 cm Kadhai with Lid, 5 Layer Healthy Duramax Non-Stick Coating - Ivory', NULL, 0, NULL, 'Elevate your cooking experience with the Duralife Die-Cast 24 cm Kadhai with Lid. This stylish kadhai features a classic ivory color and striking dark wood-finish soft-touch handles, adding elegance to your kitchen. Crafted from pure-grade die-cast aluminium, it boasts a professional-grade Duramax Japanese non-stick coating that ensures minimal oil use for healthier cooking. Highly durable and energy-efficient, this kadhai retains its shape and offers superior heat conduction. Suitable for all cooktops, it is perfect for cooking a variety of dishes, from pakodas to exotic noodles. Enjoy peace of mind with a 2-year warranty.  Key Features: Stylish Design: Classic ivory color with dark wood-finish soft-touch handles. Healthy Cooking: Duramax Japanese non-stick coating, PFOA-free. Durable Construction: Pure-grade die-cast aluminium retains shape and strength. Versatile Use: Ideal for cooking pakodas, jalebis, sabzis, noodles, biryani, and more. Energy-Efficient: Superior heat conduction saves energy and time.', '2024-07-06 12:30:41', '2024-07-06 12:30:41', 4, 0),
(13, 'Graphite 24 cm Kadhai with Lid', NULL, 0, NULL, 'Experience effortless and healthy cooking with the Graphite 24 cm Kadhai with Lid. Featuring a stunning stone finish and German Greblon non-stick coating, this kadhai not only adds beauty to your kitchen but also ensures excellent performance. Made from pure-grade virgin aluminium, it offers superior heat conduction for even cooking. The 5-layer non-stick coating is PFOA-free and abrasion-resistant, allowing for the use of metal utensils. With comfortable soft-touch handles and a durable design, this kadhai is compatible with gas, induction, and hot plates.', '2024-07-06 12:33:08', '2024-07-06 12:33:08', 4, 0),
(14, 'Nigella Tri-Ply Stainless Steel 28 cm Kadhai with Lid | 4.1 Litres | Induction Base', NULL, 0, NULL, 'Elevate your culinary skills with the Nigella Tri-Ply Stainless Steel Kadhai from Wonderchef. This premium kadhai combines modern design with unmatched functionality, perfect for everyday cooking.  Enhanced Multi-layered Construction: Features an aluminium core sandwiched between two high-grade, non-toxic steel layers for superior heat conduction and durability. Perfect Cooking Every Time: The 2.6mm thick tri-ply walls ensure even heat distribution, preventing food from burning and guaranteeing consistent results. Healthy & Delicious Meals: Requires less oil thanks to the tri-ply construction, allowing you to prepare healthier meals without sacrificing flavor. Versatile & Multifunctional: Ideal for a variety of dishes, making it a must-have for any kitchen. Compatible With All Cooktops: Suitable for gas, electric, and induction cooktops, offering maximum flexibility. Riveted Stay-cool Handles: Designed with stay-cool handles for safe handling, securely riveted to the kadhai’s body. Easy to Clean: The mirror-polished exterior adds elegance and is easy to clean, while the brushed-finish interior prevents food from sticking. Ideal For Home Chefs & Pros: Professional-grade construction makes it perfect for both home cooks and culinary experts. Long-lasting 10-year Warranty: Enjoy peace of mind with a 10-year Wonderchef warranty. Experience the best in cooking with the Nigella Tri-Ply Stainless Steel 28 cm Kadhai, combining style, health, and durability. Order now and transform your kitchen with this essential cookware.', '2024-07-06 12:35:15', '2024-07-06 12:35:15', 4, 0),
(15, 'Nigella Stainless Steel 28 cm Biryani Pot | 6.5 Liters | Silver', NULL, 0, NULL, 'Elevate your cooking experience with the Wonderchef Nigella Biryani Pot. This pot is perfect for preparing large batches of delicious biryani and other family-favorite dishes.  Optimal Cooking Experience: The tri-ply bottom with steel-aluminium-steel layers ensures excellent heat retention and even cooking, making every meal perfect. Generous Capacity: With a 6.5-liter capacity, it\'s ideal for cooking biryani, pulao, curries, and more for the whole family. Premium Quality: Crafted from food-grade stainless steel, it boasts a durable and elegant mirror finish. Energy Efficient: The induction base offers better contact with the heat source, leading to faster cooking and 30% energy savings. User-Friendly Design: Features cool touch silicone handles for a comfortable grip and an easy-pour design to prevent messy drips. Heavy Stainless Steel Lid: Ensures faster cooking while retaining moisture and nutrients for healthier meals. Easy Maintenance: Dishwasher safe for convenient cleaning. Reliable Warranty: Enjoy peace of mind with Wonderchef\'s warranty, inspired by Italian design and adhering to German quality standards. Transform your kitchen with the Wonderchef Nigella Biryani Pot and relish perfectly cooked meals every time. Order now and enjoy exceptional quality and performance.', '2024-07-06 12:38:09', '2024-07-06 12:38:09', 4, 0),
(16, 'Forza 24 cm Cast-Iron Kadhai, Pre-Seasoned Cookware, Induction Friendly, 1.9L, 3.8mm', NULL, 0, NULL, 'Bring the timeless appeal of cast-iron cookware to your kitchen with the Forza Cast-Iron Kadhai. Perfect for both traditional and modern cooking, this kadhai ensures that your meals are cooked to perfection, every time.  Classic Cast-Iron Quality: Designed for old-style slow cooking, the Forza Kadhai is perfect for preparing succulent and healthy meals, just like your dadi & nani used to make. Versatile Cooking: Suitable for a variety of dishes, from spicy pakodas and sweet jalebis to mouth-watering fried rice and noodles. Even Heat Distribution: Heavy cast-iron retains and transfers heat evenly, ensuring your food is cooked perfectly.', '2024-07-06 12:41:10', '2024-07-06 12:41:10', 4, 0),
(17, 'Ebony 30 cm Hard Anodized Deep Kadhai/Kadai with Lid - 6 Litres | Ideal for Sauteeing Veggies, Dal, and Curries | Black', NULL, 0, NULL, 'Bring home the stunning Ebony Cookware Range from Wonderchef and elevate your cooking experience. Designed with functionality and aesthetics in mind, this deep kadhai is perfect for a variety of culinary tasks.  Elegant Design: Features a stunning grey color with wooden handles, adding a sophisticated look to your kitchen. Hard Anodized Construction: The process of anodizing makes the aluminum harder and non-reactive, ensuring years of hassle-free use, faster cooking, and even heat distribution. Durable Coating: 60 microns anodized coating makes it 2.4 times harder than steel, providing exceptional durability.', '2024-07-06 12:44:36', '2024-07-06 12:44:36', 4, 0),
(18, 'Stanton 28 cm Non-stick Kadhai/Kadai with Lid - 3.4 Litres', NULL, 0, NULL, 'The Stanton 28 cm Non-stick Kadhai/Kadai is the epitome of culinary excellence, designed to bring a touch of sophistication to your kitchen. Crafted from high-quality 304 stainless steel, this kadhai ensures your food remains pure and flavorful, free from any reactions or rust. The innovative 3-ply full body construction, featuring steel-aluminium-steel layers, guarantees quick and even heating, saving energy and preventing food from burning. Its unique stainless steel honeycomb structure protects the non-stick coating, offering a robust, scratch-resistant surface that promises longevity and ease of use. The ergonomic stainless steel casting handle provides a firm and comfortable grip, making cooking a delight. Inspired by elegant Italian design and adhering to stringent German quality standards, this kadhai not only enhances your cooking experience but also adds a modern aesthetic to your kitchen. Easy to clean and maintain, the Stanton Non-stick Kadhai/Kadai is the perfect choice for both everyday meals and gourmet creations, backed by a reliable Wonderchef warranty for peace of mind.', '2024-07-06 12:48:01', '2024-07-06 12:48:01', 4, 0),
(19, 'Granite 26cm Non-Stick Wok, Glass Lid, Induction Bottom, Soft-Touch Handles, Virgin Aluminium', NULL, 0, NULL, 'The Granite 26cm Non-Stick Wok is an essential addition to any kitchen, designed to enhance your cooking and dining experience. This stylish grey wok features a granite finish that not only adds a modern aesthetic but also ensures ultimate non-stick performance. Crafted from virgin aluminium, the 3.5mm thick wok is both durable and efficient, offering fast and even heat distribution thanks to its induction bottom. The PFOA and heavy metals-free coating ensures that your meals are healthier, requiring minimal oil for cooking. With its soft-touch handles, the wok provides a comfortable and secure grip, making it perfect for stir-frying and everyday cooking. The included glass lid helps retain moisture and flavors, while the easy-to-clean surface reduces water usage by 70%, making post-cooking cleanup a breeze. Adhering to Italian design and German quality standards, this wok promises exceptional performance and durability, backed by a reliable 2-year Wonderchef warranty. Whether for personal use or as a thoughtful gift, the Granite 26cm Non-Stick Wok is an excellent choice for anyone who values quality and style in their kitchen.', '2024-07-06 12:51:35', '2024-07-06 12:51:35', 4, 0),
(20, 'Royal Velvet Non-stick 24cm Kadhai with Lid and Handles | Glass Lid | Induction Ready | Soft-touch handles |Non – Toxic', NULL, 0, NULL, 'Elevate your culinary prowess with the Wonderchef Royal Velvet 24cm Kadhai with Lid. This exquisite piece of cookware combines aesthetic appeal with functional excellence, featuring a regal purple color and a marble finish that enhances any kitchen decor. Crafted from virgin aluminium and boasting a robust 3mm thickness, it ensures durability and even heat distribution, ideal for a variety of cooking tasks.  The highlight of this kadhai is its METATUFF non-stick coating, a 5-layered marvel that guarantees scratch resistance and effortless cleaning. Enjoy healthy cooking with minimal oil, as the coating is 100% free from harmful substances like PFOA, lead, cadmium, nickel, and arsenic, meeting stringent safety standards set by USFDA and EFSA.  Designed for versatility, this kadhai can be used on both gas stoves and induction cooktops, offering flexibility in your culinary adventures. Its soft-touch handles provide a secure grip and comfort during use, while the seamless inside wall prevents food buildup, ensuring hygienic cooking and easy cleaning.', '2024-07-06 12:54:14', '2024-07-06 12:54:14', 4, 0),
(21, ' Bellagio Kadhai with Lid , Non-Stick Ceramic Coating | Non-Toxic | Pure Aluminium | PFAS and PFOA Free', NULL, 0, NULL, 'Introducing the Bellagio Kadhai with Lid, a pinnacle of culinary innovation and environmental responsibility. Crafted with non-stick ceramic coating derived from natural sand extracts, this cookware set ensures healthy cooking without compromising on performance. Made from pure virgin aluminium, it offers superior heat conductivity, enabling even and quick cooking for delicious meals every time.  The non-stick ceramic coating is not only safe for your family but also eco-friendly, being free from harmful chemicals like PFAS, PFOA, heavy metals, and nickel. This ensures minimal environmental impact while providing a durable, long-lasting cooking surface that is easy to clean.  Designed for comfort and control, the kadhai features two-tone soft-touch handles and knob that remain cool while cooking, offering a firm grip and enhancing the cooking experience. Its 3mm thickness adds durability without compromising on weight, making it easy to handle and maneuver in the kitchen.', '2024-07-06 12:58:01', '2024-07-06 12:58:01', 4, 0),
(22, 'Pre-Seasoned Ferro Light 24cm Kadhai, Non-stick cookware range, Multiple work in one', NULL, 0, NULL, 'Discover the Wonderchef Ferro Light Weight Cast-iron Cookware Range, a modern twist on classic cast-iron pans. Engineered with Gravity Moulding Technology, these pans are lighter yet retain the robust benefits of traditional cast iron. Perfect for a variety of cooking methods including stir-frying, sautéing, roasting, and slow cooking, they redefine versatility in the kitchen.  Features:  Lightweight Cast-Iron Excellence: Crafted with Gravity Moulding Technology, these pans offer the strength and durability of cast iron in a lighter, more user-friendly design. Enjoy superior quality and a better finish that enhances your cooking experience.', '2024-07-06 13:00:32', '2024-07-06 13:00:32', 4, 0),
(23, 'Duralife Die-cast 24 cm Fry Pan | 5 Layer Healthy Duramax Non-Stick Coating | Soft Touch Handle | 1.7 liter', NULL, 0, NULL, 'The Duralife Fry Pan is designed for healthy cooking with minimal oil, thanks to its PFOA-free Duramax Japanese non-stick coating, ensuring effortless food release and easy cleaning. Its robust 4mm thick base and rim offer exceptional durability and shape retention even under rigorous use. Versatile and energy-efficient, this fry pan delivers rapid and uniform heat distribution on all cooking surfaces, including gas, ceramic, and induction cooktops.  Impeccably sized at 24 cm, it accommodates a variety of dishes from fried eggs to pancakes with ease. Ideal for gifting, the Duralife Fry Pan comes with a 2-year warranty, backed by Wonderchef’s reliable after-sales service across India.', '2024-07-06 13:08:10', '2024-07-06 13:08:10', 5, 0),
(24, 'Forza Pre Seasoned 19 cm Cast Iron Fry Pan', NULL, 0, NULL, 'Experience the essence of traditional Indian cooking with Forza\'s pre-seasoned cast iron fry pan, designed to infuse rich flavors into every dish. Its robust construction ensures even heat distribution for perfect omelettes, stir-fried vegetables, and more, while its pre-seasoned surface with 100% vegetable oil enriches your meals with essential iron nutrients.  Ideal for all cooking surfaces, this versatile pan is oven, grill, and freezer safe, catering to various culinary needs with ease. Inspired by Italian design and crafted to German quality standards, Forza guarantees reliability and culinary excellence, backed by Wonderchef\'s trusted warranty.', '2024-07-06 13:12:07', '2024-07-06 13:12:07', 5, 0),
(25, 'Caesar 24 cm Non-Stick Fry Pan | Fry Pan, a fusion of class, elegance, and functionality', NULL, 0, NULL, 'Elevate your cooking with Aesar\'s finest quality die-cast pan, featuring a substantial 5mm thickness for durability and superior heat retention. It\'s equipped with Hengestone C3+, a state-of-the-art 3-layer non-stick coating that\'s PFOA-free, guaranteeing safe and healthy cooking practices.  Made from 99.9% pure grade aluminium, this pan ensures fast and even heat distribution, facilitating efficient cooking on induction, gas, electric, and glass stovetops. Enjoy the convenience of its induction base, enhancing versatility in your kitchen.  Backed by a robust 5-year warranty, Aesar promises reliability and longevity, embodying culinary perfection inspired by German craftsmanship and design excellence.', '2024-07-06 13:16:07', '2024-07-06 13:16:07', 5, 0),
(26, 'Royal Velvet Non-Stick 26 cm Fry Pan with Induction Bottom & Soft-Touch Handle', NULL, 0, NULL, 'Enhance your culinary and dining experience with the Wonderchef Royal Velvet Fry Pan, renowned for its stylish marble finish and modern design. This elegant fry pan, crafted from pure grade virgin aluminium, ensures quick and even heat distribution, making it a complete solution for healthy, low-fat, home-cooked meals. Featuring a health-friendly, 100% PFOA-free, heavy metal and nickel-free 5-layer Meta Tuff non-stick coating, it promotes daily oil-free cooking without compromising on taste. With a strong 3mm thickness, the Royal Velvet Fry Pan is built to last, while its ergonomically designed soft-touch handles and knob provide a firm grip and remain cool during cooking. Suitable for use on various cooktops, including gas stoves, ceramic plates, hobs, hot plates, infrared, and induction plates, it is incredibly versatile. Inspired by Italian design and adhering to German quality standards, Wonderchef products come with a reliable warranty, ensuring peace of mind with every purchase.', '2024-07-06 13:19:21', '2024-07-06 13:19:21', 5, 0),
(27, 'Nigella Tri-ply Stainless Steel 26 cm Fry Pan', NULL, 0, NULL, 'Experience the pinnacle of cooking excellence with the Wonderchef Nigella Tri-ply Stainless Steel Fry Pan. Designed specifically for Indian cooking, where varying temperatures are essential, this fry pan combines functionality with elegance. Available in capacities ranging from 1.8 to 2.6 liters and boasting a robust 2.5mm thickness, it ensures durability and even heat distribution for perfect results every time.  Enhanced Multi-layered Construction: The fry pan features an aluminum core sandwiched between two layers of high-grade stainless steel, offering exceptional heat conduction and unmatched durability.', '2024-07-06 13:21:45', '2024-07-06 13:21:45', 5, 0),
(28, 'Omelette Pan, Granite Non Stick Fry Pan | Bakelite handles |Non – Toxic I Virgin Aluminium| 20 cms | 1 liter', NULL, 0, NULL, 'Elevate your culinary skills with the Wonderchef Granite Non Stick Fry Pan. Crafted from virgin aluminium and adorned with a stylish grey granite finish, this pan is perfect for everyday cooking tasks like frying and preparing omelettes.  Ultimate Nonstick Perfection: Glide food effortlessly off the ultra-durable granite surface, ensuring easy cooking and cleaning every time.  Healthy Culinary Skills: Embrace a low-oil lifestyle with the PFOA-free non-stick coating, delivering healthier meals without compromising on flavor.', '2024-07-06 13:24:24', '2024-07-06 13:24:24', 5, 0),
(29, 'Caesar Non-Stick Fry Pan 26cm | Ideal for Saute / Frying | German Beechwood Handle', NULL, 0, NULL, 'Discover excellence in cooking with the Wonderchef Caesar Non-Stick Fry Pan. This world-class die-cast pan sets a gold standard in quality, blending superior performance with award-winning design.  Superlative Performance: Achieve exceptional cooking results with the heavy metal-free Greblon nonstick coating, allowing for healthy cooking with minimal oil.  Healthy Non-Stick Coating: Enjoy peace of mind with PFOA and heavy metal-free Greblon coating, ensuring durability and safety for years of use.', '2024-07-06 13:26:41', '2024-07-06 13:26:41', 5, 0),
(30, 'Granite 3 Pc Cookware Set with Lid, Non Stick', NULL, 0, NULL, 'Enhance your culinary experience with the Granite 3-Piece Cookware Set. Crafted for durability and performance, this set features a premium Meta Tuff 5-layer non-stick coating, ensuring healthy cooking without compromising on flavor. Made from pure grade virgin aluminium, it guarantees efficient heat distribution for consistent results every time you cook.  The set includes a versatile fry pan with a lid and a dosa tawa, catering to various cooking needs from frying to steaming. Compatible with gas stoves, induction cooktops, ceramic plates, and more, it offers flexibility in your kitchen. Complete with a glass lid for quick cooking and steaming, this cookware set combines Italian-inspired design with German quality standards, backed by a reliable Wonderchef warranty for peace of mind.', '2024-07-06 13:29:41', '2024-07-06 13:29:41', 5, 0),
(31, 'Caesar Forged Casserole with Glass Lid, 24cm, German Beechwood Handles, Use for Frying, Cooking Rice/Biryani, Gravies, Dal', NULL, 0, NULL, 'Introducing the Caesar Forged Casserole with Glass Lid, a pinnacle of elegance and functionality in cookware. Crafted with precision and care, this casseroles features a proprietary Meta-tuff coating and German beechwood handles that epitomize sophistication. The PFOA & PFAS free non-stick coating ensures healthy cooking, while robotic processes ensure even heat distribution for consistent results.  Key Features:  Premium Construction: Made with extra-thick rim and base forged from pure virgin aluminium (99.7%), ensuring fast heat transfer and durability.  Versatile Use: Ideal for frying, cooking rice/biryani, preparing gravies, and dal. Its induction base allows use on gas, induction, electric, and glass cooktops.', '2024-07-06 13:31:56', '2024-07-06 13:31:56', 5, 0),
(32, 'Caesar Forged Kadhai with Glass Lid, 24cm, German Beechwood Handles, Use for Frying, Cooking Rice/ Biryani, Gravies, Dals', NULL, 0, NULL, 'Discover the elegance and durability of the Caesar Forged Kadhai with Glass Lid. Crafted with a proprietary Meta-tuff coating and German beechwood handles, this cookware exudes class and functionality. With a PFOA & PFAS free non-stick coating and even heat distribution technology, it ensures lasting performance and health-conscious cooking. Ideal for frying, cooking rice/biryani, gravies, and dals, its induction base allows versatile use on gas, induction, electric, and glass cooktops. Made from 99.7% pure virgin aluminium, it facilitates fast heat transfer while maintaining food integrity. Easy to clean and maintain, this kadhai is a testament to Italian-inspired design and German quality standards, backed by a reliable Wonderchef warranty.', '2024-07-06 13:35:28', '2024-07-06 13:35:28', 5, 0),
(33, 'Caesar Forged Grill Pan, German Beechwood Handles, Use for Grilling Tikkis, Breads, Rolls, Meat, Paneer', NULL, 0, NULL, 'Experience culinary excellence with the Caesar Forged Grill Pan. Featuring a Greblon C3 non-stick coating and German beechwood handles, this pan combines elegance with functionality. Ideal for grilling tikkis, breads, rolls, meat, and paneer, it ensures even heat distribution for perfect results. Crafted from 99.7% pure virgin aluminium, it promotes fast heat transfer without compromising food quality. Use it across gas, induction, electric, and glass cooktops for versatile cooking. Easy to clean with its high-quality non-stick surface, it upholds health and safety with PFOA-free materials. Backed by Italian design and German quality standards, it includes a reliable Wonderchef warranty for peace of mind.', '2024-07-06 13:39:19', '2024-07-06 13:39:19', 5, 0),
(34, 'Pre-Seasoned Ferro Light 20cm Cast Iron Fry Pan | 800 ml', NULL, 0, NULL, 'Discover the Wonderchef Ferro Light 20cm Cast Iron Fry Pan, a lighter version of classic cast-iron cookware crafted with Gravity Moulding Technology for enhanced durability and reduced weight. Pre-seasoned with 100% vegetable oil, it ensures healthy cooking and excellent heat retention for even cooking. Featuring elegant Acacia wooden handles that stay cool, it\'s ideal for stir-frying, sautéing, roasting, and more. Compatible with gas, induction, and electric cooktops, this pan comes with a 10-year warranty against cracking or breakage, embodying Italian design and German quality standards for lasting performance.', '2024-07-06 13:42:28', '2024-07-06 13:42:28', 5, 0),
(35, 'Duralife Die-cast 24 cm Grill Pan | 5 Layer Healthy Duramax Non-Stick Coating', NULL, 0, NULL, 'Discover the Duralife Die-cast 24 cm Grill Pan, combining elegant Ivory aesthetics with practical functionality. Crafted from pure-grade aluminium and featuring a durable Duramax Japanese non-stick coating, it ensures minimal oil use and PFOA-free healthy cooking. This versatile pan cooks evenly and efficiently on gas, induction, ceramic, and more, making it ideal for a variety of dishes from burgers to tikkas. With its soft-touch handle and sturdy construction, it\'s a perfect gift choice. Backed by a 2-year warranty, it offers reliability and performance for your kitchen adventures.', '2024-07-06 13:46:31', '2024-07-06 13:46:31', 6, 0),
(36, 'Granite Non-Stick 24cm Grill Pan, 3.5mm Thickness, 1.8 litres', NULL, 0, NULL, 'Enhance your cooking with the Wonderchef Granite Non-Stick 24cm Grill Pan, featuring a stylish granite finish on virgin aluminium. This pan offers ultimate non-stick performance, allowing easy food release and effortless cleaning. It promotes healthy cooking with its PFOA-free coating, ideal for grilling veggies and meats with minimal oil. The robust 3.5mm thickness and 5-ply granite construction ensure durability and scratch resistance, maintaining its elegant appearance. Designed for efficiency, it distributes heat evenly for perfect grilling results every time. With ergonomic features like a double pour spout and easy-clean design, it\'s a thoughtful gift backed by a 2-year warranty, embodying Italian design and German quality standards.', '2024-07-06 14:07:39', '2024-07-06 14:07:39', 6, 0),
(37, 'Forza Cast-iron 26 cm Grill Pan, Pre-Seasoned Cookware, Induction Friendly', NULL, 0, NULL, 'Experience the culinary tradition with Forza Cast-Iron 26 cm Grill Pan, designed for superior cooking and health benefits. Pre-seasoned with 100% vegetable oil, it enriches your meals with essential Iron ions, perfect for grilling tikkas, kebabs, and sandwiches with minimal oil. Enjoy even heat distribution for restaurant-style cooking and durability that lasts a lifetime, backed by a 25-year warranty against defects. With a sturdy handle for easy handling and compatibility with all cooking surfaces, including oven and grill, Forza Grill Pan ensures versatile use and effortless cleaning, making it a timeless addition to your kitchen.', '2024-07-06 14:12:05', '2024-07-06 14:12:05', 6, 0),
(38, 'Pre-Seasoned Ferro Light 24cm Grill Pan, 2.5mm, Acacia Wooden Handles with new Gravity Moulding Technology', NULL, 0, NULL, 'Discover the Ferro Light 24cm Grill Pan, a modern take on classic cast-iron cookware. Crafted with Gravity Moulding Technology for lightweight durability, it features Acacia wood handles for a comfortable grip. Pre-seasoned with 100% Vegetable Oil, it enhances your cooking with essential Iron ions. Ideal for versatile cooking methods like stir-frying, roasting, and grilling, it ensures even heat distribution across all cooktops including gas, induction, and electric. Backed by a 10-year warranty, this pan combines health benefits, durability, and ease of use, making it a must-have in every kitchen.', '2024-07-06 14:14:38', '2024-07-06 14:14:38', 6, 0),
(39, 'Nigella Tri-Ply Stainless Steel 22 cm Casserole | 3.2 Litres | 2.6mm', NULL, 0, NULL, 'Experience culinary excellence with the Nigella Tri-Ply Stainless Steel 22 cm Casserole from Wonderchef. Designed for Indian cooking, its tri-ply construction with an aluminium core ensures superior heat conduction and durability. Cook nutrient-rich meals with less oil, thanks to its even heat distribution and 2.6mm thickness. Perfect for soups, biryanis, curries, and more, it\'s compatible with gas, electric, and induction cooktops. Featuring riveted cool-touch handles for safe handling and easy cleanup with a mirror-polished exterior. Backed by a 10-year warranty, it’s a must-have for every kitchen enthusiast.', '2024-07-06 14:17:06', '2024-07-06 14:17:06', 7, 0),
(40, 'Orchid Fry Pan 24cm, Austin Serving Casserole Set of 2, Gift Combo, For Family and Friends, Gift for Diwali and Other Festivals', NULL, 0, NULL, 'Celebrate the festive season with the Orchid Fry Pan and Austin Serving Casserole Set from Wonderchef, perfect for gifting or enhancing your own kitchen experience. The Orchid Fry Pan, crafted from virgin aluminium with Meta-tuff non-stick coating, ensures healthy cooking and even heat distribution. Its ergonomic handle offers a secure grip for comfortable cooking. The Austin Serving Casserole, made of rust-resistant stainless steel, keeps food fresh with special insulation and features an innovative dome-shaped glass lid to retain flavor and moisture. Backed by Wonderchef\'s Italian-inspired design and German quality standards, with a reliable warranty, it’s an ideal choice for delightful cooking and serving experiences.', '2024-07-06 14:22:21', '2024-07-06 14:22:21', 7, 0),
(41, 'Forza 25 cm Cast-Iron Casserole with Lid | Pre-Seasoned Cookware | Induction Friendly | 4.7 L | 3.8 mm', NULL, 0, NULL, 'The Forza 25 cm Cast-Iron Casserole with Lid offers the pinnacle of traditional cooking with modern reliability. Crafted for old-style slow-cooking, it brings back the magic of family recipes with its durable, pre-seasoned cast-iron construction. Ideal for both restaurant-style and home-cooked meals, this casserole evenly distributes heat for perfect biryanis, dum preparations, koftas, and curries. The heavy lid seals in moisture for tender dishes, while the ergonomic handles ensure a secure grip. Oven, grill, and freezer safe, it’s compatible with all cooking surfaces, including induction. Backed by a lifetime exchange warranty, this Forza casserole promises enduring quality and culinary excellence.', '2024-07-06 14:24:38', '2024-07-06 14:24:38', 7, 0),
(42, 'Royal Velvet 24cm Casserole with Glass Lid, Induction Ready, Soft-touch handles, 3 mm thick | 4.5 litres', NULL, 0, NULL, 'Enhance your culinary prowess with the Royal Velvet 24cm Casserole, designed to bring sophistication and functionality to your kitchen. Featuring a vibrant Regal Purple exterior and a durable METATUFF non-stick marble coating inside, this casserole combines aesthetic appeal with practicality. Enjoy healthy cooking with minimal oil, thanks to its scratch-resistant and easy-to-clean surface. Ideal for a variety of dishes from pakodas to biryanis, it offers versatility across gas stoves and induction cooktops. With soft-touch handles for a secure grip and a seamless interior for hygiene, this casserole ensures effortless cooking and cleaning. Perfect for gifting, it comes with a 2-year warranty, reflecting Wonderchef\'s commitment to Italian design and German quality standards.', '2024-07-06 14:27:34', '2024-07-06 14:27:34', 7, 0),
(43, 'Gold Stanton Stainless Steel 3 piece Casserole Set with Glass Lid, Induction & Gas Stove friendly | Set of 3 (1.6L, 2.3L, 3.1L)', NULL, 0, NULL, 'Elevate your kitchen with the Gold Stanton Casserole Set, featuring a luxurious design with golden knobs and handles. Crafted from high-quality stainless steel, these casseroles ensure even heat distribution for perfect cooking results. The set includes three sizes (1.6L, 2.3L, 3.1L), each equipped with a tempered glass lid that retains moisture and speeds up cooking. With ergonomic handles for a comfortable grip and a stylish leaf design, these casseroles are not only practical but also enhance your dining experience. Suitable for gas stoves and induction cooktops, they are easy to clean and dishwasher safe, meeting Italian design standards and German quality assurance.', '2024-07-06 14:29:55', '2024-07-06 14:29:55', 7, 0),
(44, 'Caesar Non-Stick Casserole with Lid, German Beechwood Handle, Induction Bottom, 5 mm', NULL, 0, NULL, 'Experience the ultimate in cooking with the Caesar Non-Stick Casserole. Crafted for elegance and functionality, this casserole features German beechwood handles and a knob, adding a touch of class to your kitchen. Made from high-quality die-cast aluminium with a substantial 5mm thickness, it ensures durability and even heat distribution. The Hengestone C3+, 3-layer non-stick coating, PFOA-free, guarantees healthy cooking with minimal oil. Equipped with an induction base, it\'s compatible with gas, electric, and glass stovetops. Backed by a 5-year warranty, this casserole offers reliability and performance for all your culinary adventures.', '2024-07-06 14:32:11', '2024-07-06 14:32:11', 7, 0),
(45, 'Ebony Hard Anodized Biryani Handi with Lid 3.5 L, Soft Handle', NULL, 0, NULL, 'Discover the Ebony Hard Anodized Biryani Handi, a versatile and durable addition to your kitchen. Its stunning black color and wooden handles not only enhance its appearance but also add a touch of sophistication to your cooking space. Crafted using a process of anodizing, this handi is made from aluminium that\'s harder and non-reactive, ensuring years of hassle-free cooking with faster and even heat distribution. The 60 microns anodized coating makes it exceptionally durable, being 2.4 times harder than steel. With a thickness of 3.25 mm, it\'s stain and corrosion-resistant, offering easy maintenance. Compatible with induction, gas, electric, and glass stove tops, this handi combines versatility with reliability, backed by Wonderchef\'s trusted warranty for added peace of mind. Ideal for preparing biryanis and a variety of dishes, the Ebony Hard Anodized Biryani Handi is designed to elevate your cooking experience with style and efficiency.', '2024-07-06 14:36:43', '2024-07-06 14:36:43', 7, 0),
(46, 'Stanton 20 cm Stainless Steel Casserole With Lid, Handle with Silicone Sleeve, Induction Friendly, 2.5mm, 3L', NULL, 0, NULL, 'Prepare delicious and nutritious meals with the Stanton 20 cm Stainless Steel Casserole, designed for both health and durability. Featuring a full 3-ply body with layers of Stainless Steel and Aluminium, it ensures superior heat distribution for even cooking. The 304 stainless steel construction is non-reactive with food and resistant to rust, promising long-lasting performance. Elegant stainless steel casting handles with silicone sleeves provide a comfortable grip and protection from burns. The casserole\'s ergonomic design includes easy stacking to save space in your kitchen, while its non-porous surface makes cleaning and maintenance effortless. Backed by Wonderchef\'s reliable warranty, this casserole combines functionality with style for your cooking needs.', '2024-07-06 14:39:27', '2024-07-06 14:39:27', 7, 0),
(47, 'Paniyarakkal 23 cm Non-stick, Gas Stovetop Compatible | Ideal for flavourful and Healthy Appams |  Black', NULL, 0, NULL, 'Prepare delicious and healthy appams effortlessly Paniyarakkal, designed for maximum convenience and durability. Crafted from die-cast aluminium, it accommodates up to 15 appams at once, perfect for serving family and guests. The non-stick coated surface ensures easy release of appams with minimal oil, promoting healthier cooking. This PFOA and heavy metal-free coating guarantees long-term use without health concerns. Integrated handles provide sturdy support and durability, while the well-rounded moulds ensure even cooking and perfect shapes. The die-cast technology ensures superior heat distribution and retention, maintaining consistent cooking results over time. Cleaning is hassle-free with the non-stick coating, making it easy to maintain. This Paniyarakkal combines Italian design elegance with German quality standards for an exceptional cooking experience.', '2024-07-06 14:42:44', '2024-07-06 14:42:44', 8, 0),
(48, 'Appachetty Breakfast Pan with Lid | Nonstick Cookware | Appachatty, Chetty Pan, Appam Patra, Round Bottom Kadai | 3mm Thick, 22cm', NULL, 0, NULL, 'Enjoy the convenience of making soft and delicious appams Appachetty Breakfast Pan. This 22 cm deep pan features a non-stick surface for healthy, oil-free cooking without compromising on taste. It includes a stainless steel lid with a heat-resistant soft-touch knob for easy handling. The ergonomically designed soft-touch handles ensure a firm grip, even with wet hands, enhancing comfort during cooking. Crafted from pure grade aluminium and equipped with a thick, PFOA-free non-stick coating, this pan is durable and scratch-resistant, making it safe for use with metal spoons. Cleaning is effortless thanks to the non-stick surface. Backed by a 2-year warranty, this pan combines Italian design elegance with German quality standards, ensuring reliability and eco-friendliness in your kitchen.', '2024-07-06 14:45:39', '2024-07-06 14:45:39', 8, 0),
(49, 'Non-Stick Appa Kara Cookware with 12 cavities | Appam PatraPaniyarakkal | Paniyaram, Appam Pan, Pan Cake Maker, Ponganal Maker, Kuzhi Paniyaram, Paddu Tawa, Cool Touch Bakelite Handle', NULL, 0, NULL, 'Prepare delicious traditional Appas effortlessly with the Wonderchef Non-Stick Appa Kara Cookware. This versatile pan features 12 cavities, perfect for making Appam Patra, Paniyarakkal, and more. It boasts a technologically advanced MetaTuff 5-layer non-stick coating that ensures food slides off easily and minimizes the need for oil, promoting healthy cooking. The coating is 100% free from harmful chemicals like PFOA, lead, cadmium, nickel, and arsenic, ensuring a safe cooking experience.  Crafted from pure grade aluminium, this cookware is sturdy and durable, designed to withstand daily use. The seamless inside wall prevents food residue buildup, maintaining hygiene even with continual use. Ergonomically designed cool-touch Bakelite handles provide a firm grip and comfort during cooking. The pan is stain and corrosion-resistant, making it easy to clean and maintain.  Backed by a 1-year reliable Wonderchef warranty, this cookware combines Italian design elegance with German quality standards, ensuring eco-friendliness and performance in your kitchen.', '2024-07-06 14:49:26', '2024-07-06 14:49:26', 8, 0),
(50, 'Nigella Tri-Ply 14 cm Sauce Pan (1.2,2.2 Liters), 2.5 mm Thickness | Silver', NULL, 0, NULL, 'Experience the excellence of cooking with the Nigella Tri-Ply 14 cm Sauce Pan. Ideal for Indian cooking, this sauce pan is crafted from tri-ply stainless steel, combining durability with efficient heat distribution. With a capacity of 1.2 liters and a thickness of 2.5 mm, it ensures strength and sturdiness for all your culinary needs.  Perfect for boiling milk, water, or preparing tea and coffee, the Nigella sauce pan retains nutrients and flavors without compromising on quality. Its tri-ply construction includes an aluminium layer sandwiched between layers of high-grade 18/8 stainless steel, making it highly heat conductive and compatible with induction cooktops.', '2024-07-06 14:53:04', '2024-07-06 14:53:04', 9, 0),
(51, 'Bellagio Sauce Pan | 16 cm | 1.4 L | Non-Toxic | Pure Aluminium | 3mm Thickness | Two-Tone Soft-Touch Handle and Knob | Firm Grip', NULL, 0, NULL, 'Introducing the Bellagio Sauce Pan, a revolutionary addition to your kitchen offering exceptional cooking performance with a focus on environmental responsibility. Crafted from virgin aluminium, known for its superior heat conductivity, this pan ensures even and quick cooking results. The non-stick ceramic coating, derived from natural sand-based ingredients, guarantees a safe cooking surface free from PFAS, PFOA, heavy metals, and nickel, promoting both health safety and environmental sustainability.  With a thickness of 3mm, the Bellagio Sauce Pan is durable yet lightweight, making it easy to handle. Its two-tone soft-touch handle and knob provide a secure grip while remaining cool during cooking, enhancing comfort and usability. Suitable for various cooking surfaces including gas stoves, ceramic plates, induction cooktops, and more, this pan is versatile and convenient for everyday cooking needs.', '2024-07-06 14:56:11', '2024-07-06 14:56:11', 9, 0),
(52, 'Paniyarakkal 23 cm Non-stick, Ideal for flavourful and Healthy Appams | Gas Stovetop Compatible | Black', NULL, 0, NULL, 'Prepare delicious and healthy appams effortlessly with the Paniyarakkal. This 23 cm non-stick pan features a perfectly moulded structure for making up to 15 appams at once. Enjoy low-oil cooking with its PFOA and heavy metal-free coating, ensuring durability and safety. Integrated handles offer sturdy support, while even heat distribution and retention ensure consistent cooking results. Cleaning is a breeze thanks to the non-stick surface. Backed by a 2-year warranty, this pan combines Italian design elegance with German quality standards for a premium cooking experience.', '2024-07-06 14:58:55', '2024-07-06 14:58:55', 11, 0),
(53, 'Nigella Tri-Ply Stainless Steel 22 cm Casserole | 3.2 Litres | 2.6mm', NULL, 0, NULL, 'Experience culinary excellence with the Nigella Tri-Ply Stainless Steel 22 cm Casserole from Wonderchef. Designed for Indian cooking, its tri-ply construction with an aluminium core ensures superior heat conduction and durability. Cook nutrient-rich meals with less oil, thanks to its even heat distribution and 2.6mm thickness. Perfect for soups, biryanis, curries, and more, it\'s compatible with gas, electric, and induction cooktops. Featuring riveted cool-touch handles for safe handling and easy cleanup with a mirror-polished exterior. Backed by a 10-year warranty, it’s a must-have for every kitchen enthusiast.', '2024-07-06 14:17:06', '2024-07-06 14:17:06', 12, 0);
